/**
 * STROKE_ORDER_DATA — authored stroke order for the letter-writing guide
 * animation (CPP-393). Each character maps to an ordered list of strokes;
 * each stroke is a list of anchor points [x, y] normalised 0..1 against
 * the character's own ink bounding box (y down, 0,0 = top-left). Anchors
 * only need to be approximately right — languages/static/languages/js/
 * stroke_order.js snaps each one to the nearest pixel of the actual
 * rendered glyph's skeleton and walks the skeleton between them, so the
 * traced path always follows the real letterform.
 *
 * A character with NO entry here must fall back to the static glyph with
 * no direction arrow — never a guessed path (see stroke_order.js's
 * module doc). This is what keeps an unauthored or unreviewed script
 * honest rather than silently wrong.
 *
 * Coverage: all 579 characters seeded by
 * languages/management/commands/seed_language_exercises.py (65 Latin,
 * 59 Sinhala, 31 Tamil, 231 CJK, 142 kana, 51 Hangul) have an entry,
 * enforced by languages/tests/test_cpp393_stroke_order_data.py.
 *
 * Confidence:
 *   - latin:   hand-authored. The 52 English A-Z/a-z entries come from
 *              conventional English manuscript/print handwriting order
 *              (see the ticket's reference link). The 13 French accented
 *              letters (à â ç é è ê ë î ï ô ù û ü, added when French was
 *              seeded) are each the existing base letter's own
 *              hand-authored stroke(s), rescaled to leave room above (or
 *              below, for ç's cedilla) for a final accent-mark stroke —
 *              not independently re-authored from a reference.
 *   - sinhala: MIXED. 32 letters (12 independent vowels: අ ආ ඇ ඈ ඉ ඊ උ ඌ
 *              එ ඒ ඔ ඕ; 20 consonants: ක ග ච ජ ට ඩ ණ ත ද න ප බ ම ය ර ල ව ස
 *              හ ළ) are transcribed from the numbered stroke-and-arrow
 *              tracing worksheets at edibear.com/books?tag=SINHALA — each
 *              anchor's pixel position was read directly off that
 *              letter's own worksheet image and normalised against that
 *              same letter's ink bounding box (not an eyeballed generic
 *              proportion), so relative shape/proportions should track
 *              the worksheet closely. Still not a measured/traced export,
 *              so a native-speaker visual pass is worthwhile before
 *              calling it fully verified. The
 *              remaining 27 letters (the 6 vocalic/diphthong vowels and
 *              21 aspirated/retroflex consonants edibear.com doesn't
 *              cover) are still the original TEMPLATE-GENERATED generic
 *              anticlockwise loop and MUST be reviewed and authored
 *              letter-by-letter by a native Sinhala writer before this
 *              ships — CPP-393 AC.
 *   - tamil:   MIXED. 27 letters (11 independent vowels: அ ஆ இ உ ஊ எ ஏ ஐ ஒ ஓ
 *              ஔ; 16 consonants: க ச ட ண த ந ப ம ய ர ல வ ழ ள ற ன) are
 *              transcribed from the numbered stroke-and-arrow tracing
 *              worksheets at edibear.com/books?tag=TAMIL — real per-letter
 *              stroke count, order and direction, anchor coordinates read
 *              directly off each worksheet's diagram. Still not a
 *              measured/traced export, so a native-speaker visual pass is
 *              worthwhile. ஈ, ங, ஞ and ஃ are still the original
 *              TEMPLATE-GENERATED generic anticlockwise loop — edibear.com
 *              doesn't cover ங/ஞ/ஃ, and ஈ's worksheet diagram didn't match
 *              the actual glyph. All four MUST be reviewed and authored
 *              by a native Tamil writer before this ships — CPP-393 AC.
 *   - cjk:      hand-authored from standard Kaishu (regular script) stroke
 *              order — general knowledge of well-documented, standardised
 *              stroke order, not derived from an external worksheet
 *              reference like Sinhala/Tamil. Covers numbers 一-十, all 214
 *              Kangxi radicals (simplified forms substituted where a
 *              simplified standalone character exists; radicals whose
 *              "simplified form" is a bound component only, e.g. 言/讠,
 *              金/钅, 糸/纟, 食/饣, 阜|邑/阝, 衣/衤, 艸/艹, 辵/辶, keep their
 *              traditional standalone form since a bound component can't
 *              be traced as its own character), and 11 common compound
 *              words (including 中, not itself an official radical).
 *              Still worth a native-speaker visual pass, same as the
 *              others.
 *   - kana:     hand-authored from standard Japanese elementary stroke-order
 *              charts (Monbukagakusho-style stroke count/order), general
 *              knowledge rather than a traced worksheet. Covers all 46
 *              basic (seion) hiragana + 46 basic katakana in gojuon order.
 *              The 20 dakuten (゛) and 5 handakuten (゜) forms per kana
 *              script (50 total) are each the existing base kana's own
 *              hand-authored stroke(s), rescaled to leave room for a final
 *              mark stroke — same derivation technique as the French
 *              accented letters above, not independently re-authored.
 *              Yoon (combination) kana like きゃ/キャ are out of scope —
 *              two-character digraphs, not individual letters, matching
 *              the "letters not the whole writing system" scope used for
 *              Mandarin (radicals, not arbitrary compounds). Still worth a
 *              native-speaker visual pass, same as the others.
 *   - hangul:   hand-authored for the 14 basic consonants + 10 basic
 *              vowels only (24 characters) — the rest of the 51-character
 *              Korean set (5 doubled consonants, 11 compound vowels, 11
 *              syllable-final consonant clusters) is DERIVED, not
 *              independently authored: each of those 27 characters is
 *              literally two (or three) of the 24 base letters written
 *              side by side (e.g. ㄲ = ㄱ+ㄱ, ㅘ = ㅗ+ㅏ, ㄳ = ㄱ+ㅅ), so
 *              its strokes are the component letters' own hand-authored
 *              strokes rescaled into side-by-side columns — same
 *              derivation technique as the French accented letters and
 *              Japanese dakuten above. Uses Hangul Compatibility Jamo
 *              codepoints (U+3131-U+318E), which render as standalone
 *              letterforms, not the positional Hangul Jamo block used
 *              only inside precomposed syllable blocks. Still worth a
 *              native-speaker visual pass, same as the others.
 */

